using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Profiling;
public static class TripoSummerCurvePack {
 static readonly string[] fields={"px","py","pz","qx","qy","qz","qw","sx","sy","sz"};
 static AnimationCurve[] Curves(NativeSupportPoseData.Joint j)=>fields.Select(f=>(AnimationCurve)typeof(NativeSupportPoseData.Joint).GetField(f).GetValue(j)).ToArray();
 static byte[] Signature(AnimationCurve c){using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,System.Text.Encoding.UTF8,true)){w.Write((int)c.preWrapMode);w.Write((int)c.postWrapMode);w.Write(c.length);foreach(var k in c.keys){w.Write(k.time);w.Write(k.value);w.Write(k.inTangent);w.Write(k.outTangent);w.Write(k.inWeight);w.Write(k.outWeight);w.Write((int)k.weightedMode);}}return m.ToArray();}}
 public static void PackOnly(){Directory.CreateDirectory("SummerEvidence/Binary");var log=new List<string>{"asset,sourceCurves,uniqueCurves,sourceKeys,uniqueKeys,yamlBytes,packedBytes,rawBinaryBytes,oldAssetRuntimeBytes,packedAssetRuntimeBytes,decodeMs,keyBitsExact"};foreach(string guid in AssetDatabase.FindAssets("t:NativeSupportPoseData",new[]{"Assets/NativeSupport/Summer"})){string path=AssetDatabase.GUIDToAssetPath(guid);var data=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(path);if(data.PackedAsset)continue;var js=data.joints;if(js==null||js.Length==0)continue;var old=js.SelectMany(Curves).Where(c=>c!=null).ToArray();var oldSignatures=js.Select(j=>Curves(j).Select(c=>c==null?null:Signature(c)).ToArray()).ToArray();long oldMem=Profiler.GetRuntimeMemorySizeLong(data),yaml=new FileInfo(path).Length;var curves=new List<AnimationCurve>();var index=new Dictionary<string,int>();var mappings=new List<int[]>();foreach(var j in js){var map=new int[10];var cs=Curves(j);for(int i=0;i<10;i++){if(cs[i]==null){map[i]=-1;continue;}string hash=Convert.ToBase64String(Signature(cs[i]));if(!index.TryGetValue(hash,out var id)){id=curves.Count;curves.Add(cs[i]);index.Add(hash,id);}map[i]=id;}mappings.Add(map);}var times=new List<float[]>();var ti=new Dictionary<string,int>();var cti=new List<int>();foreach(var c in curves){var ts=c.keys.Select(k=>k.time).ToArray();using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,System.Text.Encoding.UTF8,true))foreach(var t in ts)w.Write(t);string key=Convert.ToBase64String(m.ToArray());if(!ti.TryGetValue(key,out var id)){id=times.Count;ti[key]=id;times.Add(ts);}cti.Add(id);}}
 byte[] raw;using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,System.Text.Encoding.UTF8,true)){w.Write(0x31434e4c);w.Write(times.Count);foreach(var ts in times){w.Write(ts.Length);foreach(float t in ts)w.Write(t);}w.Write(curves.Count);for(int c=0;c<curves.Count;c++){w.Write((int)curves[c].preWrapMode);w.Write((int)curves[c].postWrapMode);w.Write(cti[c]);foreach(var k in curves[c].keys){w.Write(k.value);w.Write(k.inTangent);w.Write(k.outTangent);w.Write(k.inWeight);w.Write(k.outWeight);w.Write((int)k.weightedMode);}}w.Write(js.Length);foreach(var map in mappings)foreach(int id in map)w.Write(id);}raw=m.ToArray();}
 string binary=path+".curves.bytes";using(var file=File.Create(binary))using(var zip=new DeflateStream(file,System.IO.Compression.CompressionLevel.Optimal))zip.Write(raw,0,raw.Length);AssetDatabase.ImportAsset(binary,ImportAssetOptions.ForceSynchronousImport);data.SetPacked(AssetDatabase.LoadAssetAtPath<TextAsset>(binary),js.Select(j=>j.path).ToArray());EditorUtility.SetDirty(data);AssetDatabase.SaveAssets();var clock=System.Diagnostics.Stopwatch.StartNew();var decoded=data.joints;clock.Stop();for(int j=0;j<decoded.Length;j++){var cs=Curves(decoded[j]);for(int c=0;c<10;c++)if(oldSignatures[j][c]!=null&&!oldSignatures[j][c].SequenceEqual(Signature(cs[c])))throw new Exception("Lossless native key bits differ "+path+" "+j+" "+c);}
 log.Add(string.Join(",",path,old.Length,curves.Count,old.Sum(c=>c.length),curves.Sum(c=>c.length),yaml,new FileInfo(binary).Length,raw.Length,oldMem,Profiler.GetRuntimeMemorySizeLong(data),clock.Elapsed.TotalMilliseconds,"true"));data.ReleaseDecoded();}
 File.WriteAllLines("SummerEvidence/Binary/packing.csv",log);Debug.Log("AGENT_RESULT lossless native curves packed with exact key-bit gates");}

}
